import subprocess, sys, json, re
jar, tare = sys.argv[1], float(sys.argv[2])
target = tare + 250.0
def call(*a):
    p = subprocess.run(list(a), capture_output=True, text=True)
    out = p.stdout + p.stderr
    if p.returncode != 0: print("ERR", a, out); sys.exit(1)
    return out
def read():
    out = call("scale","read")
    m = re.search(r"(-?\d+\.\d+)", out)
    return float(m.group(1))
g = read(); print("start", g)
while g < target - 55: call("robot","dose","bulk"); g = read()
while g < target - 12: call("robot","dose","coarse"); g = read()
while g < target - 1.0: call("robot","dose","fine"); g = read()
while g < target - 0.05: call("robot","dose","micro"); g = read()
while g > target + 0.20:
    call("robot","remove"); g = read()
    while g < target - 0.05: call("robot","dose","micro"); g = read()
print("net %.3f" % (g - tare))
print(call("checkweigher","check"))
call("robot","pick",jar); call("robot","place","rack")
EOF
